files.sync/programs.py:
"""Copies programs from the scheduling vendor into the site's catalog."""

from app.vendor import client
from app.catalog import remove_program, upsert_program

EXCLUDED_PROGRAM_IDS = {4101, 4117, 4123, 4188}


def sync_programs():
    for program in client.list_programs():
        if program["id"] in EXCLUDED_PROGRAM_IDS:
            remove_program(program["id"])
            continue
        if not program["published"]:
            remove_program(program["id"])
            continue
        upsert_program(program)
